parameters.functionCode:
// Classificeer inbound reply op basis van keywords.
// Output: interest_level (High/Medium/Low), reply_type (interest/objection/timing/other), urgency (Urgent/Normal), next_stage, next_action

const results = [];

for (const item of items) {
  const email = item.json;
  const body = (email.snippet || email.textPlain || '').toLowerCase();
  const subject = (email.subject || '').toLowerCase();
  const text = `${subject} ${body}`;

  let interestLevel = 'Unknown';
  let replyType = 'other';
  let urgency = 'Normal';
  let nextStage = email.current_stage || 'Contacted';
  let nextAction = 'Review reply handmatig';

  // Interest signals
  const highIntent = /\b(interesse|graag|wanneer kunnen we|offerte|samples?|proefdoos|meeting|call|bellen|afspraak|deze week|zo snel mogelijk)\b/.test(text);
  const mediumIntent = /\b(misschien|later|volgende maand|niet nu|terugkomen|overwegen)\b/.test(text);
  const objection = /\b(te duur|geen interesse|al leverancier|nee bedankt|stop|unsubscribe)\b/.test(text);
  const timing = /\b(volgende week|volgende maand|kwartaal|later dit jaar|eind van)\b/.test(text);

  if (objection) {
    interestLevel = 'Low';
    replyType = 'objection';
    nextStage = /nee bedankt|geen interesse|stop/.test(text) ? 'Closed Lost' : 'Engaged';
    nextAction = 'Bezwaar adresseren of sluiten';
  } else if (highIntent) {
    interestLevel = 'High';
    replyType = 'interest';
    urgency = /deze week|zo snel mogelijk|asap/.test(text) ? 'Urgent' : 'Normal';
    nextStage = /meeting|call|afspraak/.test(text) ? 'Meeting Booked' : 'Engaged';
    nextAction = urgency === 'Urgent' ? 'Direct bellen of mailen vandaag' : 'Reageren binnen 24u met voorstel';
  } else if (timing) {
    interestLevel = 'Medium';
    replyType = 'timing';
    nextStage = 'Engaged';
    nextAction = 'Follow-up reminder inplannen voor genoemde datum';
  } else if (mediumIntent) {
    interestLevel = 'Medium';
    replyType = 'timing';
    nextStage = 'Engaged';
    nextAction = 'Follow-up over 2 weken met extra waarde';
  } else {
    nextStage = 'Engaged';
    nextAction = 'Handmatig reviewen';
  }

  results.push({
    json: {
      lead_id: email.lead_id,
      record_id: email.record_id,
      company_name: email.company_name,
      contact_name: email.contact_name,
      contact_email: email.from,
      reply_snippet: email.snippet,
      interest_level: interestLevel,
      reply_type: replyType,
      urgency,
      next_stage: nextStage,
      next_action: nextAction,
      hot_lead: interestLevel === 'High' && urgency === 'Urgent',
      last_contact_date: new Date().toISOString().split('T')[0]
    }
  });
}

return results;

